mapper.select:
SELECT * FROM production_order

    is_deleted = 0

        AND order_no LIKE CONCAT('%', #{dto.orderNo}, '%')


        AND category_id = #{dto.categoryId}


        AND order_status = #{dto.orderStatus}


        AND current_process = #{dto.currentProcess}


        AND material_prepare_status = #{dto.materialPrepareStatus}


        AND responsible_person = #{dto.responsiblePerson}


        AND plan_start_time >= #{dto.planStartTimeStart}


        AND plan_start_time <= #{dto.planStartTimeEnd}


        AND create_time >= #{dto.createStartTime}


        AND create_time <= #{dto.createEndTime}


ORDER BY ${dto.orderBy} ${dto.orderType}
